SELECT 
FROM messages
WHERE session_id = #{sessionId}

  AND id < #{beforeId}

ORDER BY id DESC
LIMIT #{limit}

SELECT 
FROM messages
WHERE session_id = #{sessionId}
  AND turn_id = #{turnId}
  AND ordinal = #{ordinal}

SELECT EXISTS (
    SELECT 1 FROM messages
    WHERE session_id = #{sessionId}
      AND id < #{id}
)

